import {observationEditionOperation,observationEditionCSV,observationCalibration} from './observation_editions.mjs';
import {observationEditionHTML} from '../web/observation_editions.mjs';
import {benchmarkOperation,readBenchmark,benchmarkCSV} from './benchmark_workspace.mjs';
import {benchmarkHTML} from './benchmark_reports.mjs';
import {flowStudyBundle,flowLoadBundle} from './flow_bundles.mjs';
import {flowLoadOperation,readFlowLoadResult,flowLoadCSV} from './flow_results.mjs';
import {renderFlowStudy,renderFlowLoads} from './flow_reports.mjs';
import {nativeSourceOperation} from './native_observations.mjs';
import {reconciliationOperation,reconciliationReport,reconciliationCSV} from './source_reconciliation.mjs';
import {sourceReviewHTML} from '../web/source_reconciliation.mjs';
import {intakeOperation} from './intake.mjs';
import {handbackOperation,handbackMember} from './source_handback.mjs';
import {flowOperation,readFlowStudy,flowCSV} from './flow_workspace.mjs';
import {largeOperation} from './large_http.mjs';
import {previewCollection,receiveCollection,listCollections,publishCollection,readEdition,editionMember,editionBundle} from './collections.mjs';
import fs from 'node:fs/promises';
import path from 'node:path';
import {MeasurementWorkspace} from './workspace.mjs';
import {InputError,safeJSON} from './parse.mjs';
import {providerQuery,fetchProvider} from './providers.mjs';
import {calibrationExport,calibrationCSV,pairedLoads} from './calibration.mjs';
const DEFAULT_BASE='/api/measurement-workspace';
const MAX_BODY=Number(process.env.MEASUREMENTS_UPLOAD_BYTES)||128*1024*1024;
async function readBody(request) {
  if(request.body!==undefined)return request.body;
  let size=0;const chunks=[];
  for await(const chunk of request){size+=chunk.length;if(size>MAX_BODY)throw new InputError('Upload exceeds configured process limit',413);chunks.push(chunk);}
  try{return safeJSON(new TextDecoder('utf-8',{fatal:true}).decode(Buffer.concat(chunks)));}catch(e){if(e instanceof InputError)throw e;throw new InputError('Request must be UTF-8 JSON');}
}
async function baseData(directory,name) {
  try{return JSON.parse(await fs.readFile(path.join(directory,name),'utf8'));}catch(e){if(e.code==='ENOENT')return [];throw e;}
}
export function createMeasurementHandler({directory,base=DEFAULT_BASE,fetcher=globalThis.fetch,workspace,reachProvider}={}) {
  let store=workspace;
  const get=()=>store||(store=new MeasurementWorkspace(directory));
  function send(response,status,value,type='application/json; charset=utf-8',filename) {
    response.statusCode=status;response.setHeader('Content-Type',type);response.setHeader('Cache-Control','no-store');response.setHeader('X-Content-Type-Options','nosniff');
    if(filename)response.setHeader('Content-Disposition',`attachment; filename="${filename}"`);
    response.end(type.startsWith('application/json')?JSON.stringify(value):value);
  }
  const handler=async(request,response,next)=>{
    const url=new URL(request.originalUrl||request.url,'http://localhost');
    if(!url.pathname.startsWith(base+'/')&&url.pathname!==base){if(next)return next();send(response,404,{error:'Not found'});return;}
    try{
    if(!['GET','HEAD'].includes(request.method)&&request.headers.origin){
      let origin;try{origin=new URL(request.headers.origin);}catch{throw new InputError('Invalid request origin',403);}
      if(origin.host!==request.headers.host)throw new InputError('Cross-origin writes are not accepted',403);
    }
    const parts=url.pathname.slice(base.length).split('/').filter(Boolean).map(decodeURIComponent),method=request.method,query=Object.fromEntries(url.searchParams);
      const s=get();
      if(parts[0]==='observation-editions'){
        if(method==='GET'&&parts[1]==='editions'&&parts.length===4&&['report.html','observations.csv','report.csv','calibration.json'].includes(parts[3])){
          const edition=await observationEditionOperation(s,'GET',['editions',parts[2]],{},{}),format=parts[3];
          const value=format==='report.html'?observationEditionHTML(edition):format==='calibration.json'?observationCalibration(edition):observationEditionCSV(edition);
          const type=format==='report.html'?'text/html; charset=utf-8':format==='calibration.json'?'application/json; charset=utf-8':'text/csv; charset=utf-8';
          send(response,200,value,type,'observation-edition-'+parts[2].slice(0,12)+'-'+format);return;
        }
        send(response,200,await observationEditionOperation(s,method,parts.slice(1),query,method==='POST'?await readBody(request):{}));return;
      }
      if(parts[0]==='native-observations'){send(response,200,nativeSourceOperation(s,method,parts.slice(1),query));return;}
      if(parts[0]==='benchmarks'){
        if(method==='GET'&&parts[1]==='studies'&&parts.length===4&&['report.html','rows.csv','periods.csv'].includes(parts[3])){
          const study=readBenchmark(s,parts[2]),html=parts[3]==='report.html';
          send(response,200,html?benchmarkHTML(study):benchmarkCSV(study,parts[3].split('.')[0]),html?'text/html; charset=utf-8':'text/csv; charset=utf-8','observed-benchmark-'+study.id.slice(0,12)+'-'+parts[3]);return;
        }
        send(response,200,await benchmarkOperation(s,method,parts.slice(1),method==='POST'?await readBody(request):{}));return;
      }
      if(parts[0]==='intake'){send(response,200,intakeOperation(s,method,parts.slice(1),['POST','PUT'].includes(method)?await readBody(request):{}));return;}
      if(parts[0]==='reconciliation'){
        if(method==='GET'&&parts[1]==='reports'&&parts.length===4&&parts[3]==='report.csv'){
          send(response,200,reconciliationCSV(reconciliationReport(s,parts[2])),'text/csv; charset=utf-8','source-reconciliation.csv');return;
        }
        if(method==='GET'&&parts[1]==='reports'&&parts.length===4&&parts[3]==='report.html'){
          send(response,200,sourceReviewHTML(reconciliationReport(s,parts[2])),'text/html; charset=utf-8','source-reconciliation.html');return;
        }
        send(response,200,reconciliationOperation(s,method,parts.slice(1),query,method==='POST'?await readBody(request):{}));return;
      }
      if(parts[0]==='flow'){
        if(method==='GET'&&parts.length===4&&parts[3]==='bundle'){
          if(parts[1]==='studies'){send(response,200,flowStudyBundle(s,parts[2]));return;}
          if(parts[1]==='load-results'){send(response,200,flowLoadBundle(s,parts[2]));return;}
        }
        if(method==='GET'&&parts[1]==='studies'&&parts.length===4&&parts[3]==='report.html'){send(response,200,renderFlowStudy(readFlowStudy(s,parts[2])),'text/html; charset=utf-8','daily-discharge-study.html');return;}
        if(parts[1]?.startsWith('load-')){
          if(method==='GET'&&parts[1]==='load-results'&&parts.length===4){
            const result=readFlowLoadResult(s,parts[2]),format=parts[3];
            if(format==='report.html'){send(response,200,renderFlowLoads(result),'text/html; charset=utf-8','concentration-discharge.html');return;}
            if(['daily.csv','periods.csv','context.csv','annual.csv'].includes(format)){send(response,200,flowLoadCSV(result,format.split('.')[0]),'text/csv; charset=utf-8',format);return;}
          }
          send(response,200,await flowLoadOperation(s,method,parts.slice(1),method==='POST'?await readBody(request):{}));return;
        }
        if(method==='GET'&&parts[1]==='studies'&&parts.length===4&&['daily.csv','periods.csv','samples.csv'].includes(parts[3])){send(response,200,flowCSV(readFlowStudy(s,parts[2]),parts[3].split('.')[0]),'text/csv; charset=utf-8',parts[3]);return;}
        send(response,200,await flowOperation(s,method,parts.slice(1),method==='POST'?await readBody(request):{}));return;
      }
      if(parts[0]==='large'){send(response,200,await largeOperation(s,method,parts.slice(1),query,['POST','PUT'].includes(method)?await readBody(request):{}));return;}
      if(parts[0]==='handbacks'){
        if(method==='GET'&&parts.length===3&&parts[2]==='files'){
          const member=handbackMember(s,parts[1],query.name);
          response.writeHead(200,{'Content-Type':member.type,'Content-Length':member.data.length,'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Content-Disposition':'attachment; filename="source-return-member"'});
          response.end(member.data);return;
        }
        send(response,200,handbackOperation(s,method,parts.slice(1),query,method==='POST'?await readBody(request):{}));return;
      }
      const reaches=async()=>reachProvider?await reachProvider():await baseData(s.directory,'reaches.json');
      if(parts[0]==='collections'){
        if(method==='GET'&&parts.length===1){send(response,200,{collections:listCollections(s)});return;}
        if(method==='POST'&&parts[1]==='preview'&&parts.length===2){send(response,200,previewCollection(s,await readBody(request)));return;}
        if(method==='POST'&&parts[1]==='receive'&&parts.length===2){send(response,200,receiveCollection(s,await readBody(request)));return;}
        if(method==='POST'&&parts.length===3&&parts[2]==='publish'){send(response,200,publishCollection(s,parts[1]));return;}
        if(method==='GET'&&parts[2]==='editions'&&parts[3]){
          if(parts.length===5&&parts[4]==='bundle'){send(response,200,editionBundle(s,parts[1],parts[3]));return;}
          if(parts.length===4){send(response,200,readEdition(s,parts[1],parts[3]));return;}
          const member=editionMember(s,parts[1],parts[3],parts.slice(4).join('/'));
          response.writeHead(200,{'Content-Type':member.type,'Content-Length':member.data.length,'X-Content-Type-Options':'nosniff'});response.end(member.data);return;
        }
      }
      if(method==='GET'&&!parts.length){send(response,200,{...s.summary(),reaches:await reaches()});return;}
      if(method==='GET'&&parts.length===1&&parts[0]==='snapshot'){send(response,200,s.fullSnapshot(query));return;}
      if(method==='GET'&&parts[0]==='records'){send(response,200,parts[1]?s.record(parts[1]):s.records(query));return;}
      if(method==='POST'&&parts[0]==='preview'){send(response,200,s.preview(await readBody(request)));return;}
      if(method==='POST'&&parts[0]==='imports'){send(response,201,s.import(await readBody(request)));return;}
      if(method==='GET'&&parts[0]==='sources'&&parts[1]){
        const source=s.source(parts[1]);
        if(parts[2]==='original')send(response,200,source.content,source.kind==='usgs-daily'?'application/geo+json; charset=utf-8':'text/csv; charset=utf-8',`source-${source.id.slice(0,12)}.${source.kind==='usgs-daily'?'geojson':'csv'}`);
        else if(parts[2]==='rejected')send(response,200,JSON.parse(source.rejected),'application/json; charset=utf-8',`source-${source.id.slice(0,12)}-rejected.json`);
        else send(response,200,{...source,content:undefined,mapping:JSON.parse(source.mapping),summary:JSON.parse(source.summary),rejected:JSON.parse(source.rejected),origin:JSON.parse(source.origin)});
        return;
      }
      if(method==='POST'&&parts[0]==='provider-query'){send(response,200,providerQuery(await readBody(request)));return;}
      if(method==='POST'&&parts[0]==='provider-fetch'){
        const input=await readBody(request),controller=new AbortController();
        const abort=()=>{if(!response.writableEnded)controller.abort();};response.once('close',abort);
        try{const source=await fetchProvider(input,{fetcher,signal:controller.signal});send(response,200,{source,preview:s.preview(source)});}finally{response.removeListener('close',abort);}return;
      }
      if(method==='PUT'&&parts[0]==='stations'&&parts[2]==='mapping'){
        const reachRows=await reaches(),input=await readBody(request),selected=reachRows.find(r=>r.id===input.reachId);input.domainSourceReference=selected?.sourceSha256?{sourceSha256:selected.sourceSha256,sourcePath:selected.source_path}:null;send(response,200,s.mapping(parts[1],input,reachRows.map(r=>r.id)));return;
      }
      if(method==='PUT'&&parts[0]==='records'&&parts[2]==='review'){send(response,200,s.review(parts[1],await readBody(request)));return;}
      if(method==='GET'&&parts[0]==='export.csv'){send(response,200,s.exportRecords(query),'text/csv; charset=utf-8','measurements.csv');return;}
      if(method==='POST'&&parts[0]==='calibration'){
        const input=await readBody(request),value=calibrationExport(s,input.filters||{});
        if(input.format==='csv')send(response,200,calibrationCSV(value),'text/csv; charset=utf-8','calibration-input.csv');else send(response,200,value);return;
      }
      if(method==='POST'&&parts[0]==='paired-loads'){send(response,200,pairedLoads(s,await readBody(request)));return;}
      if(method==='GET'&&parts[0]==='exports'&&parts.length===1){
        const offset=Number(query.offset??0),limit=Number(query.limit??20);
        if(!Number.isSafeInteger(offset)||offset<0||!Number.isSafeInteger(limit)||limit<1||limit>100)throw new InputError('Choose a nonnegative offset and a result page size from 1 to 100.');
        const value=s.readConsistent(()=>({total:s.db.prepare('SELECT COUNT(*) n FROM exports').get().n,offset,limit,
          rows:s.db.prepare('SELECT id,kind,created_at AS createdAt,revision AS workspaceRevision FROM exports ORDER BY created_at DESC,id DESC LIMIT ? OFFSET ?').all(limit,offset)}));
        send(response,200,value);return;
      }
      if(method==='GET'&&parts[0]==='exports'&&parts[1]){const row=s.db.prepare('SELECT content FROM exports WHERE id=?').get(parts[1]);if(!row)throw new InputError('Export not found',404);send(response,200,JSON.parse(row.content),'application/json; charset=utf-8','measurement-export.json');return;}
      if(method==='GET'&&parts[0]==='portable'){send(response,200,s.portable(),'application/json; charset=utf-8','upper-savannah-measurements.json');return;}
      if(method==='POST'&&parts[0]==='receive'){send(response,201,s.receive(await readBody(request)));return;}
      send(response,404,{error:'Measurement operation not found'});
    }catch(error){if(response.destroyed)return;send(response,error instanceof InputError?error.status:500,{error:error instanceof InputError?error.message:'Measurement operation failed; details are in the server log.'});if(!(error instanceof InputError))console.error('[measurements]',error);}
  };
  handler.close=()=>store?.close();return handler;
}

#!/usr/bin/env node
import {observationEditionOperation,observationEditionCSV,observationCalibration} from './observation_editions.mjs';
import {observationEditionHTML} from '../web/observation_editions.mjs';
import {benchmarkOperation,readBenchmark,benchmarkCSV} from './benchmark_workspace.mjs';
import {benchmarkHTML} from './benchmark_reports.mjs';
import {runReconciliationCLI} from './reconciliation_cli.mjs';
import {publishExactFile} from './file_product.mjs';
import {flowStudyBundle,flowLoadBundle} from './flow_bundles.mjs';
import {flowLoadOperation,readFlowLoadResult,flowLoadCSV} from './flow_results.mjs';
import {renderFlowStudy,renderFlowLoads} from './flow_reports.mjs';
import {flowOperation,readFlowStudy,flowCSV} from './flow_workspace.mjs';
import {runSourceHandbackCLI} from './source_handback_cli.mjs';
import {runLargeCLI} from './large_cli.mjs';
import {collectionFromFiles,previewCollection,receiveCollection,listCollections,publishCollection} from './collections.mjs';
import fs from 'node:fs/promises';
import path from 'node:path';
import http from 'node:http';
import {fileURLToPath} from 'node:url';
import {MeasurementWorkspace} from './workspace.mjs';
import {createMeasurementHandler} from './http.mjs';
import {fetchProvider} from './providers.mjs';
import {calibrationExport,calibrationCSV,pairedLoads} from './calibration.mjs';
const [command='help',...args]=process.argv.slice(2), options={};
for(let i=0;i<args.length;i++){if(!args[i].startsWith('--')||args[i+1]===undefined)throw new Error('Options require --name value pairs');options[args[i].slice(2)]=args[++i];}
const directory=path.resolve(options.workspace||process.env.DATA_DIR||'./data');
const readText=async file=>new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await fs.readFile(file));
const output=async value=>{const text=typeof value==='string'?value:JSON.stringify(value,null,2)+'\n';if(options.output)await fs.writeFile(options.output,text);else process.stdout.write(text);};
if(command.startsWith('source-handback-'))await runSourceHandbackCLI(command.slice(16),options,directory);
else if(command.startsWith('large-'))await runLargeCLI(command.slice(6),options,directory);
else if(command==='help')console.log(`Measurements workspace, Node >=22.16\n\nobservation-edition-catalogue|observation-edition-list --workspace ./data\nobservation-edition-inspect|observation-edition-preview|observation-edition-save --workspace ./data --file selection.json\nobservation-edition-read|observation-edition-report|observation-edition-csv|observation-edition-calibration --workspace ./data --id EDITION_ID --output result.json\n\nbenchmark-catalogue|benchmark-project --workspace ./data --output complete.json\nbenchmark-preview|benchmark-save|benchmark-drafts|benchmark-receive|benchmark-abandon --workspace ./data --file exact-request.json --output result.json\nbenchmark-read|benchmark-request|benchmark-draft|benchmark-report|benchmark-rows|benchmark-periods --workspace ./data --id ORIGINAL_ID --output result.json\n\nreconciliation-catalogue|reconciliation-reports --workspace ./data\nreconciliation-groups --workspace ./data --file scope.json\nreconciliation-group --workspace ./data --id LOGICAL_KEY\nreconciliation-decide|reconciliation-save-report --workspace ./data --file reviewed-input.json\nreconciliation-report --workspace ./data --id REPORT_ID --format json|csv|html --output report.json\n\nflow-catalogue --workspace ./data\nflow-inspect|flow-preview|flow-save|flow-receive|flow-compare --workspace ./data --file input.json\nflow-load-preview|flow-load-save --workspace ./data --file load-selection.json\nflow-load-catalogue --workspace ./data\nflow-load-read|flow-load-report|flow-load-periods --workspace ./data --id ID --output result.json\nflow-bundle|flow-load-bundle --workspace ./data --id ID --output complete.zip\nflow-report --workspace ./data --id ID --output report.html\nflow-read|flow-daily|flow-periods|flow-samples --workspace ./data --id ID --output result.json\n\nsource-handback-list --workspace ./data\nsource-handback-preview|source-handback-publish --workspace ./data --selection selection.json --output result.json\nsource-handback-inspect --workspace ./data --id RETURN_SHA\nsource-handback-bundle --workspace ./data --id RETURN_SHA --output returned.zip\nsource-handback-receive --workspace ./data --file returned.zip\n\nlarge-prepare|large-import --workspace ./data --file original.csv --kind wqp --label Source\nlarge-commit --workspace ./data --intake ID\nlarge-status --workspace ./data\nlarge-export --workspace ./data --output ./complete-edition\nlarge-receive --workspace ./empty-data --file complete-edition/project.zip\n\ncollection-preview|collection-receive --workspace ./data --manifest collection.json --source-root ./originals\ncollection-publish --workspace ./data --id COLLECTION_SHA\ncollections --workspace ./data\nserve --workspace ./data --port 3101\npreview|import --workspace ./data --kind wqp|stations|usgs-daily --file input.csv --label Source\nfetch --workspace ./data --kind wqp|stations|usgs-daily --station USGS-... --from YYYY-MM-DD --to YYYY-MM-DD\nsummary|records|calibration|export|portable --workspace ./data --output result.json\nreceive --workspace ./empty-data --file complete-workspace.json\nmap --workspace ./data --station ORG-ID --reach r1 --reviewer Name --reason Rationale\nreview --workspace ./data --id HASH --state include|exclude|pending --reviewer Name --reason Rationale\nloads --workspace ./data --station ORG-ID --flow-station USGS-ID --parameter tn|tp --reason Rationale\n\nThe server also exposes the original-app integration API /api/measurement-workspace.\n`);
else if(command==='serve'){
  const handler=createMeasurementHandler({directory}),publicDir=fileURLToPath(new URL('../web/',import.meta.url));
  const token=process.env.MEASUREMENTS_INTERNAL_TOKEN;
  const server=http.createServer(async(req,res)=>{
    if(token&&req.headers['x-measurement-internal-token']!==token){res.statusCode=403;res.end('Forbidden');return;}
    if(req.headers.origin){try{if(new URL(req.headers.origin).host!==req.headers.host){res.statusCode=403;res.end('Cross-origin request rejected');return;}}catch{res.statusCode=403;res.end('Invalid origin');return;}}
    if(req.url.startsWith('/api/measurement-workspace'))return handler(req,res);
    const name=new URL(req.url,'http://localhost').pathname;
    if(name==='/'){res.setHeader('Content-Type','text/html; charset=utf-8');return res.end(`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Upper Savannah · Measured data</title><body style="margin:0"><section id="large-files"></section><section id="collections"></section><main id="measurements"></main><script type="module">import{mountLargeFilePanel}from'/measurements/large_files.mjs';import{mountMeasurements}from'/measurements/workspace.js';import{mountCollectionPanel}from'/measurements/collections.mjs';const desk=mountMeasurements(document.getElementById('measurements'));mountLargeFilePanel(document.getElementById('large-files'),{refresh:()=>desk.refresh()});mountCollectionPanel(document.getElementById('collections'),{request:(path,method='GET',payload)=>fetch('/api/measurement-workspace'+path,{method,headers:{'Content-Type':'application/json'},body:payload===undefined?undefined:JSON.stringify(payload)}),refresh:()=>desk.refresh()});</script></body></html>`);}
    const files={'/measurements/observation_editions.mjs':['observation_editions.mjs','text/javascript'],'/measurements/observation_editions.css':['observation_editions.css','text/css'],'/measurements/benchmarks.mjs':['benchmarks.mjs','text/javascript'],'/measurements/source_handback.mjs':['source_handback.mjs','text/javascript'],'/measurements/source_handback.css':['source_handback.css','text/css'],'/measurements/flow_loads_ui.mjs':['flow_loads_ui.mjs','text/javascript'],'/measurements/intake.mjs':['intake.mjs','text/javascript'],'/measurements/source_reconciliation.mjs':['source_reconciliation.mjs','text/javascript'],'/measurements/source_reconciliation.css':['source_reconciliation.css','text/css'],'/measurements/results.mjs':['results.mjs','text/javascript'],'/measurements/flow_editions.mjs':['flow_editions.mjs','text/javascript'],'/measurements/flow_editions.css':['flow_editions.css','text/css'],'/measurements/large_files.mjs':['large_files.mjs','text/javascript'],'/measurements/workspace.js':['workspace.js','text/javascript'],'/measurements/workspace.css':['workspace.css','text/css'],'/measurements/collections.mjs':['collections.mjs','text/javascript']};
    if(files[name])try{const[file,mime]=files[name];res.setHeader('Content-Type',mime+'; charset=utf-8');res.end(await fs.readFile(path.join(publicDir,file)));return;}catch(error){console.error(error);}
    res.statusCode=404;res.end('Not found');
  });
  server.listen(Number(options.port||3101),options.host||'127.0.0.1',()=>console.log(JSON.stringify({ready:true,host:options.host||'127.0.0.1',port:server.address().port,pid:process.pid})));
  if(token){process.stdin.resume();process.stdin.once('end',()=>server.close(()=>{handler.close();process.exit(0);}));}
  for(const signal of ['SIGINT','SIGTERM'])process.on(signal,()=>server.close(()=>{handler.close();process.exit(0);}));
}else{
  const w=new MeasurementWorkspace(directory);
  try{
    const input=options.file?{kind:options.kind||'wqp',text:await readText(options.file),label:options.label||path.basename(options.file),mapping:options.mapping?JSON.parse(await fs.readFile(options.mapping,'utf8')):{}}:null;
    if(command.startsWith('observation-edition-')){
      const op=command.slice('observation-edition-'.length),body=input?JSON.parse(input.text):{};
      if(['read','report','csv','calibration'].includes(op)){
        if(!options.id)throw Error('Select the original observation edition with --id.');
        const edition=await observationEditionOperation(w,'GET',['editions',options.id],{},{});
        await output(op==='read'?edition:op==='report'?observationEditionHTML(edition):op==='csv'?observationEditionCSV(edition):observationCalibration(edition));
      }else if(op==='catalogue'||op==='list')await output(await observationEditionOperation(w,'GET',op==='list'?['editions']:[],{},{}));
      else if(['inspect','preview','save'].includes(op)){
        if(!input)throw Error('Supply the complete reviewed selection with --file.');
        await output(await observationEditionOperation(w,'POST',[op==='save'?'editions':op],{},body));
      }else throw Error('Unknown observation edition operation: '+op);
    }
    else if(command.startsWith('benchmark-')){
      const op=command.slice(10),body=input?JSON.parse(input.text):{};
      if(['report','rows','periods'].includes(op)){const study=readBenchmark(w,options.id);await output(op==='report'?benchmarkHTML(study):benchmarkCSV(study,op));}
      else if(['read','request','draft'].includes(op))await output(await benchmarkOperation(w,'GET',[{read:'studies',request:'requests',draft:'drafts'}[op],options.id]));
      else await output(await benchmarkOperation(w,['catalogue','project'].includes(op)?'GET':'POST',[op],body));
    }
    else if(command.startsWith('reconciliation-'))await runReconciliationCLI(command.slice('reconciliation-'.length),options,w,{readText,output});
    else if(command.startsWith('flow-')){
      const op=command.slice(5);
      if(op==='bundle'||op==='load-bundle'){
        if(!options.output)throw Error('A complete ZIP requires --output FILE.zip');
        const bundle=op==='bundle'?flowStudyBundle(w,options.id):flowLoadBundle(w,options.id);
        await publishExactFile(options.output,Buffer.from(bundle.base64,'base64'));
        process.stdout.write(JSON.stringify({output:options.output,name:bundle.name,bytes:bundle.bytes,sha256:bundle.sha256})+'\n');
      }
      else if(op==='report')await output(renderFlowStudy(readFlowStudy(w,options.id)));
      else if(op==='load-report')await output(renderFlowLoads(readFlowLoadResult(w,options.id)));
      else if(op==='load-read')await output(readFlowLoadResult(w,options.id));
      else if(['load-daily','load-periods','load-context','load-annual'].includes(op))await output(flowLoadCSV(readFlowLoadResult(w,options.id),op.slice(5)));
      else if(op.startsWith('load-'))await output(await flowLoadOperation(w,op==='load-catalogue'?'GET':'POST',[op],input?JSON.parse(input.text):{}));
      else if(op==='read')await output(readFlowStudy(w,options.id));
      else if(['daily','periods','samples'].includes(op))await output(flowCSV(readFlowStudy(w,options.id),op));
      else await output(await flowOperation(w,op==='catalogue'?'GET':'POST',[op],input?JSON.parse(input.text):{}));
    }
    else if(command==='preview')await output(w.preview(input));
    else if(command==='import')await output(w.import(input));
    else if(command==='fetch')await output(w.import(await fetchProvider({kind:options.kind||'wqp',stationId:options.station,huc:options.huc,from:options.from,to:options.to,characteristic:options.characteristic,label:options.label})));
    else if(command==='collection-preview'||command==='collection-receive'){const manifest=JSON.parse(await readText(options.manifest));const received=collectionFromFiles(manifest,options['source-root']||path.dirname(path.resolve(options.manifest)));await output(command==='collection-preview'?previewCollection(w,received):receiveCollection(w,received));}
    else if(command==='collections')await output(listCollections(w));
    else if(command==='collection-publish')await output(publishCollection(w,options.id));
    else if(command==='summary')await output(w.summary());
    else if(command==='records')await output(w.records({stationId:options.station,parameter:options.parameter,limit:options.limit,offset:options.offset}));
    else if(command==='export')await output(w.exportRecords());
    else if(command==='calibration'){const x=calibrationExport(w,{stationId:options.station,parameter:options.parameter});await output(options.format==='csv'?calibrationCSV(x):x);}
    else if(command==='portable')await output(w.portable());
    else if(command==='receive')await output(w.receive(JSON.parse(input.text)));
    else if(command==='map'){const reaches=JSON.parse(await fs.readFile(path.join(directory,'reaches.json'),'utf8'));await output(w.mapping(options.station,{reachId:options.reach,reviewer:options.reviewer,reason:options.reason},reaches.map(x=>x.id)));}
    else if(command==='review')await output(w.review(options.id,{state:options.state,reviewer:options.reviewer,reason:options.reason,selectVersion:options['select-version']==='true'}));
    else if(command==='loads')await output(pairedLoads(w,{stationId:options.station,flowStationId:options['flow-station'],parameter:options.parameter,rationale:options.reason,from:options.from,to:options.to}));
    else throw new Error('Unknown command: '+command);
  }finally{w.close();}
}

import {mountObservationEditions} from './observation_editions.mjs';
import {mountSourceHandback} from './source_handback.mjs';
import {mountGuidedIntake} from './intake.mjs';
import {describeResult,renderResult,resultHTML,resultCSV,renderSourceInspection,reasonText,measurementValue,renderObservationContext} from './results.mjs';
import {mountFlowEditions} from './flow_editions.mjs';
import {mountBenchmarks} from './benchmarks.mjs';
import {mountSourceReconciliation} from './source_reconciliation.mjs';
/** Framework-independent measured-data workflow, mounted in the native operator. */
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=(name,input)=>`<label>${name}${input}</label>`;
const option=(value,text,selected='')=>`<option value="${esc(value)}"${value===selected?' selected':''}>${esc(text)}</option>`;
const num=value=>value===null||value===undefined?'—':Number(value).toLocaleString(undefined,{maximumSignificantDigits:8});
const readText=async file=>new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await file.arrayBuffer());
const stamp=value=>value?new Date(value).toLocaleString():'—';
export function mountMeasurements(host,{base='/api/measurement-workspace',css='/measurements/workspace.css',transport,initialBenchmarkState=null,sourceHandbackState=null,onSourceHandbackState=()=>{},sourceHandbackCss='/measurements/source_handback.css',observationEditionState=null,onObservationEditionState=()=>{},observationEditionCss=null}={}){
  if(!(host instanceof Element))throw new TypeError('An existing DOM element is required');
  const style=document.createElement('link');style.rel='stylesheet';style.href=css;document.head.append(style);
  const controller=new AbortController();let dead=false,source=null,preview=null,summary=null,page=null,tab='sources',offset=0,filters={},selected=null,busy=false,handbackDesk=null,handbackSnapshot=sourceHandbackState,handbackGeneration=0,flowDesk=null,flowSnapshot=null,benchmarkDesk=null,benchmarkSnapshot=initialBenchmarkState,benchmarkLeavePrepared=false,sourceReviewDesk=null,sourceReviewSnapshot=null,observationEditionDesk=null,observationEditionSnapshot=observationEditionState,result=null,resultId='',resultOffsets={},history=null,historyOffset=0;
  host.classList.add('mw');
  host.innerHTML=`<header class="mw-head"><div><div class="mw-eyebrow">UPPER SAVANNAH / OPERATOR WORKSPACE</div><h1>Measured data</h1><p>Receive originals. Inspect measurements. Assign native reaches. Export reviewed inputs.</p></div><button data-action="refresh">Refresh</button></header><div class="mw-stats" aria-label="Workspace totals"></div><nav class="mw-nav" aria-label="Measured data"><button data-tab="sources">Receive sources</button><button data-tab="records">Measurements</button><button data-tab="stations">Station assignments</button><button data-tab="flow">Daily flow</button><button data-tab="benchmarks">Benchmarks</button><button data-tab="source-review">Source versions</button><button data-tab="observation-editions">Observation editions</button><button data-tab="exports">Exports &amp; handover</button><button data-tab="handback">Source returns</button><button data-tab="results">Saved results</button><button data-tab="archive">Source archive</button></nav><div class="mw-status" role="status" aria-live="polite">Opening saved workspace…</div><section class="mw-content"></section>`;
  const area=host.querySelector('.mw-content'),status=host.querySelector('.mw-status');
  function message(text,error=false){status.textContent=text;status.dataset.error=String(error);}
  async function request(path='',method='GET',value){return transport?await transport(path,method,value):await fetch(base+path,{method,credentials:'same-origin',signal:controller.signal,headers:value===undefined?{}:{'Content-Type':'application/json'},body:value===undefined?undefined:JSON.stringify(value)});}
  async function api(path='',method='GET',value){
    if(value!==undefined&&new TextEncoder().encode(JSON.stringify(value)).byteLength>128*1024*1024)throw new Error('The complete JSON request exceeds the native 128 MiB route. Original file and unfinished inputs remain in the guided preparation; download them or use the existing large-file intake.');
    const result=await request(path,method,value);
    const text=await result.text();if(dead){const error=new Error('Measurement view was closed');error.name='AbortError';throw error;}let data;try{data=JSON.parse(text);}catch{throw new Error('The operator returned an unexpected response. Saved sources remain available.');}
    if(!result.ok)throw new Error(data.error||`HTTP ${result.status}`);return data;
  }
  async function task(operation){if(busy)return;busy=true;host.setAttribute('aria-busy','true');try{await operation();}catch(error){if(error.name!=='AbortError')message(error.message,true);}finally{busy=false;if(!dead)host.setAttribute('aria-busy','false');}}
  const intake=mountGuidedIntake({api,onImported:()=>refresh()});
  function stationOptions(value=''){return option('','Select an imported station',value)+(summary?.stations||[]).map(s=>option(s.id,`${s.id} · ${s.name}`,value)).join('');}
  function statBar(){host.querySelector('.mw-stats').innerHTML=[['Measurements',summary.recordCount],['Stations',summary.stations.length],['Original sources',summary.imports.length],['Saved exports',summary.exportCount],['Revision',summary.revision]].map(([k,v])=>`<div><strong>${num(v)}</strong><span>${esc(k)}</span></div>`).join('');}
  async function refresh(){await stopBenchmarks();summary=await api();if(dead)return;statBar();if(tab==='records')await loadRecords();else if(tab==='results')await loadHistory();else render();message(`Workspace revision ${summary.revision} loaded. Originals and review history are retained locally.`);}
  function stopHandback(){handbackGeneration++;if(handbackDesk){handbackSnapshot=handbackDesk.snapshot();onSourceHandbackState(handbackSnapshot);handbackDesk.destroy();handbackDesk=null;}}
  function renderHandback(){
    area.replaceChildren();const node=document.createElement('div');area.append(node);const token=++handbackGeneration;
    handbackDesk=mountSourceHandback(node,{request,css:sourceHandbackCss,initialState:handbackSnapshot,
      onStateChange:value=>{if(!dead&&token===handbackGeneration){handbackSnapshot=value;onSourceHandbackState(value);}},
      refresh:async()=>{const value=await api();if(dead||token!==handbackGeneration)return;summary=value;statBar();}});
  }
  async function stopBenchmarks(){if(benchmarkDesk){await benchmarkDesk.prepareLeave();benchmarkSnapshot=benchmarkDesk.snapshot();benchmarkDesk.destroy();benchmarkDesk=null;}}
  function renderBenchmarks(){area.replaceChildren();const node=document.createElement('div');area.append(node);benchmarkDesk=mountBenchmarks(node,{request,initialState:benchmarkSnapshot,onRevision:revision=>{if(summary){summary.revision=revision;statBar();}}});}
  function stopFlow(){if(flowDesk){flowSnapshot=flowDesk.snapshot();flowDesk.destroy();flowDesk=null;}}
  function renderFlow(){area.replaceChildren();const node=document.createElement('div');area.append(node);flowDesk=mountFlowEditions(node,{api:(path,{method='GET',value}={})=>api(path,method,value),request,initialState:flowSnapshot});}
  function rememberObservationEdition(value){observationEditionSnapshot=value;onObservationEditionState(value);}
  function stopObservationEdition(){if(observationEditionDesk){rememberObservationEdition(observationEditionDesk.snapshot());observationEditionDesk.destroy();observationEditionDesk=null;}}
  function renderObservationEdition(){
    area.replaceChildren();const node=document.createElement('div');area.append(node);
    observationEditionDesk=mountObservationEditions(node,{
      api,request,css:observationEditionCss||css.replace(/[^/]*$/,'observation_editions.css'),initialState:observationEditionSnapshot||{},
      onStateChange:rememberObservationEdition,
      onChanged:({revision})=>{if(!dead&&summary){summary.revision=revision;statBar();}},
      openRecord:id=>task(async()=>{stopObservationEdition();tab='records';selected=null;await loadRecords();if(!dead)await inspect(id);}),
      openExports:()=>task(async()=>{stopObservationEdition();tab='exports';selected=null;render();})
    });
  }
  function stopSourceReview(){if(sourceReviewDesk){sourceReviewSnapshot=sourceReviewDesk.snapshot();sourceReviewDesk.destroy();sourceReviewDesk=null;}}
  function renderSourceReview(){
    area.replaceChildren();const node=document.createElement('div');area.append(node);
    sourceReviewDesk=mountSourceReconciliation(node,{
      request,css:css.replace(/[^/]*$/,'source_reconciliation.css'),initialState:sourceReviewSnapshot||{},
      onStateChange:value=>{sourceReviewSnapshot=value;},
      onChanged:({revision})=>{if(!dead&&summary){summary.revision=revision;statBar();}},
      openRecord:id=>task(async()=>{stopSourceReview();tab='records';selected=null;await loadRecords();if(!dead)await inspect(id);}),
      openExports:()=>task(async()=>{stopSourceReview();tab='exports';selected=null;render();})
    });
  }
  function render(){stopHandback();stopFlow();stopSourceReview();stopObservationEdition();if(!summary)return;for(const b of host.querySelectorAll('[data-tab]'))b.setAttribute('aria-current',String(b.dataset.tab===tab));({sources:renderSources,records:renderRecords,stations:renderStations,handback:renderHandback,flow:renderFlow,benchmarks:renderBenchmarks,'source-review':renderSourceReview,'observation-editions':renderObservationEdition,exports:renderExports,results:renderResults,archive:renderArchive})[tab]();}
  function renderSources(){area.innerHTML=`<div class="mw-grid"><div data-guided-intake></div><section class="mw-panel"><h2>Retrieve public observations</h2><p>WQX 3.0 chemistry and stations; USGS OGC daily mean discharge. The complete query and original response pages are retained.</p><form id="mw-provider">${label('Dataset',`<select name="kind">${option('wqp','WQX 3.0 chemistry')}${option('stations','WQX 3.0 stations')}${option('usgs-daily','USGS daily discharge')}</select>`)}${label('Station identifier','<input name="stationId" placeholder="USGS-… or the exact agency station ID">')}${label('Or an eight-digit HUC','<input name="huc" inputmode="numeric" maxlength="8" placeholder="Exact source watershed identifier">')}<div class="mw-two">${label('From','<input name="from" type="date" required>')}${label('Through','<input name="to" type="date" required>')}</div>${label('Characteristic, optional','<input name="characteristic" placeholder="Exact WQP characteristic name">')}<div class="mw-buttons"><button type="submit">Retrieve &amp; inspect</button><button type="button" data-action="query">Show complete query</button></div></form><div id="mw-query"></div></section></div><section class="mw-preview" aria-label="Source inspection"></section>`;area.querySelector('[data-guided-intake]').append(intake.element);renderPreview();}
  function renderPreview(){const box=area.querySelector('.mw-preview');if(!box)return;if(!preview){box.innerHTML='<p class="mw-muted">Choose a source above. Inspection does not change the workspace.</p>';return;}
    const p=preview;box.innerHTML=`<div class="mw-panel"><div class="mw-panel-head"><h2>Source inspection</h2><button data-action="commit"${!p.rows?' disabled':''}>Import complete source</button></div><p><strong>${num(p.rows)}</strong> accepted rows · <strong>${num(p.rejectedCount)}</strong> rejected rows · ${num(p.stationCount)} stations · ${num(p.censored)} censored results.</p><p>Showing ${num(p.previewCount)} representative source rows below. The import retains the entire original and every rejection.</p><dl><dt>Source</dt><dd>${esc(source.label)}</dd><dt>SHA-256</dt><dd class="mw-mono">${esc(p.contentSha)}</dd></dl>${recordTable(p.sample,false)}<details><summary>Quality flags, mapped columns and rejected rows</summary>${renderSourceInspection({...p,label:source.label,kind:source.kind,origin:source.origin||{}})}</details></div>`;}
  function recordTable(rows,inspect=true){if(!rows?.length)return '<p class="mw-empty">No measurements in this selection.</p>';return `<div class="mw-table-wrap"><table><thead><tr><th>Source date</th><th>Station</th><th>Constituent</th><th>Result</th><th>Fraction / basis</th><th>Review / eligibility</th>${inspect?'<th>Inspect</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.sampledDate||'—')}</td><td class="mw-mono">${esc(r.stationId||r.id)}</td><td>${esc(r.parameter||r.name||'Station')}</td><td class="mw-number">${esc(measurementValue(r))}</td><td>${esc(r.fraction||'—')} / ${esc(r.basis||'—')}</td><td>${r.eligible?(r.eligible.ok?'Usable measured input':esc(r.eligible.reasons.map(reasonText).join(' '))):esc((r.issues||[]).join(', ')||'No parse flags')}</td>${inspect?`<td><button data-record="${esc(r.id)}">Inspect</button></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
  async function loadRecords(){page=await api('/records?'+new URLSearchParams({...filters,offset,limit:50}));if(!dead)render();}
  function renderRecords(){area.innerHTML=`<section class="mw-panel"><div class="mw-panel-head"><h2>Measurements</h2><a class="mw-button" href="${base}/export.csv?${new URLSearchParams(filters)}" download>Export selection CSV</a></div><form id="mw-filter" class="mw-filters">${label('Station',`<select name="stationId">${option('','All stations')}${summary.stations.map(s=>option(s.id,s.id,filters.stationId)).join('')}</select>`)}${label('Constituent',`<select name="parameter">${option('','All constituents')}${[...new Set(summary.parameters.map(x=>x.parameter))].map(x=>option(x,x,filters.parameter)).join('')}</select>`)}${label('From',`<input type="date" name="from" value="${esc(filters.from||'')}">`)}${label('Through',`<input type="date" name="to" value="${esc(filters.to||'')}">`)}<button>Apply filters</button></form><p>${num(page?.total||0)} matching records. Censored values are bounds, never substituted point measurements.</p>${recordTable(page?.rows)}<div class="mw-buttons"><button data-action="previous"${offset===0?' disabled':''}>Previous</button><span>${num(offset+((page?.rows.length||0)?1:0))}–${num(offset+(page?.rows.length||0))} of ${num(page?.total||0)}</span><button data-action="next"${!page||offset+page.rows.length>=page.total?' disabled':''}>Next</button></div></section><section id="mw-inspector"></section>`;if(selected)renderInspector();}
  async function inspect(id){selected=await api('/records/'+encodeURIComponent(id));renderInspector();area.querySelector('#mw-inspector')?.scrollIntoView({block:'nearest',behavior:'smooth'});}
  function renderInspector(){const box=area.querySelector('#mw-inspector');if(!box||!selected)return;const r=selected;box.innerHTML=`<section class="mw-panel"><div class="mw-panel-head"><h2>Measurement detail</h2><button data-action="close-detail">Close</button></div><dl><dt>Identity</dt><dd class="mw-mono">${esc(r.id)}</dd><dt>Reported</dt><dd>${esc(r.reportedValue)} ${esc(r.reportedUnit)} · ${esc(r.characteristic)}</dd><dt>Normalized</dt><dd>${num(r.value)} ${esc(r.unit)}; ${esc(r.censor)} censoring; lower ${num(r.lower)}, upper ${num(r.upper)}</dd><dt>Time support</dt><dd>${esc(r.sampledDate)} / ${esc(r.sampledAt||r.sourceTime||'date only')} / ${esc(r.timePrecision)} / ${esc(r.timeZone||'zone not supplied')}</dd><dt>Method / laboratory</dt><dd>${esc(r.method||'Unspecified')} / ${esc(r.laboratory||'Unspecified')}</dd><dt>Flags</dt><dd>${esc(r.issues.map(reasonText).join(' ')||'None')}</dd><dt>Native reach</dt><dd>${esc(r.mapping?.reachId||'Unassigned')}</dd><dt>Input eligibility</dt><dd>${esc(r.eligible.ok?'Usable measured input':r.eligible.reasons.map(reasonText).join(' '))}</dd></dl>${renderObservationContext(r)}<form id="mw-review"><div class="mw-two">${label('Review decision',`<select name="state">${['pending','include','exclude'].map(x=>option(x,x,r.review.state)).join('')}</select>`)}${label('Reviewer',`<input name="reviewer" required value="${esc(r.review.reviewer||'')}">`)}</div>${label('Rationale',`<textarea name="reason" required rows="2">${esc(r.review.reason||'')}</textarea>`)}${r.variantCount>1?'<label class="mw-check"><input type="checkbox" name="selectVersion"> Choose this included source revision; retain all alternatives.</label>':''}<button>Save review</button></form><details><summary>Source revisions (${r.variantCount})</summary><div class="mw-buttons">${r.variants.map(id=>`<button data-record="${esc(id)}"${id===r.id?' disabled':''}>${esc(id.slice(0,16))}${id===r.selectedVersion?' · selected':''}</button>`).join('')}</div></details><details><summary>Complete original row and provenance</summary><pre>${esc(JSON.stringify({raw:r.raw,sources:r.sources,detectionLimits:r.detectionLimits,characteristicInterpretation:r.characteristicInterpretation,detectionInterpretation:r.detectionInterpretation,history:r.history},null,2))}</pre></details></section>`;}
  function renderStations(){area.innerHTML=`<section class="mw-panel"><h2>Explicit station-to-reach assignments</h2><p>Choose reach identifiers supplied by the original Workspace. Coordinates and datum are shown for interpretation; proximity alone never assigns a station.</p>${!summary.reaches.length?'<p class="mw-notice">No native reaches are connected. Attach the original Workspace reach resolver to enable assignments.</p>':''}${!summary.stations.length?'<p class="mw-empty">Import chemistry or station metadata to begin.</p>':''}${summary.stations.map(s=>`<details class="mw-station"><summary><strong>${esc(s.id)}</strong> · ${esc(s.name)} <span>${num(s.recordCount)} records · ${esc(s.mapping?.reachId||'Unassigned')}</span></summary><p>Latitude ${num(s.latitude)}, longitude ${num(s.longitude)} · datum ${esc(s.datum||'not supplied')}</p><form data-station-form="${esc(s.id)}"><div class="mw-two">${label('Original native reach',`<select name="reachId">${option('','Unassigned',s.mapping?.reachId||'')}${summary.reaches.map(r=>option(r.id,r.name?`${r.id} · ${r.name}`:r.id,s.mapping?.reachId)).join('')}</select>`)}${label('Reviewer',`<input name="reviewer" required value="${esc(s.mapping?.reviewer||'')}">`)}</div>${label('Assignment rationale',`<textarea name="reason" rows="2" required>${esc(s.mapping?.reason||'')}</textarea>`)}<button>Save assignment</button></form></details>`).join('')}</section>`;}
  function renderExports(){area.innerHTML=`<div class="mw-grid"><section class="mw-panel"><h2>Reviewed measurement inputs</h2><p>Complete accepted and excluded populations, exact units and fractions, explicit reach IDs, source references, and exclusion reasons. Downstream calibration retains control of model and temporal matching.</p><p class="mw-notice">The native annual quantities PO4_KG, NH4_KG and NO3_KG require a scientific load derivation. They are not aliases for discrete concentrations.</p><div class="mw-buttons"><button data-action="calibration">Create input package</button><a class="mw-button" href="${base}/export.csv" download>All measurements CSV</a></div><div id="mw-export-result"></div></section><section class="mw-panel"><h2>Independently editable handover</h2><p>Export originals, canonical records, source-row provenance, station metadata, assignments, reviews, alternative revisions and saved exports. The receiver reparses originals and verifies canonical values before committing.</p><button data-action="portable">Export complete workspace</button><form id="mw-receive">${label('Complete workspace JSON','<input type="file" name="file" accept=".json" required>')}<p>Receiving creates data only in an empty measurement workspace. Existing work is retained.</p><button>Receive verified workspace</button></form></section></div><section class="mw-panel"><h2>Explicit concentration–discharge pairing</h2><p>Pairs a discrete total-nitrogen or total-phosphorus measurement with one approved daily mean discharge on the same source calendar date. Retains unpaired rows and ambiguity reasons.</p><form id="mw-loads"><div class="mw-two">${label('Chemistry station',`<select name="stationId" required>${stationOptions()}</select>`)}${label('Discharge station',`<select name="flowStationId" required>${stationOptions()}</select>`)}</div>${label('Constituent',`<select name="parameter">${option('tn','Total nitrogen, as N')}${option('tp','Total phosphorus, as P')}</select>`)}${label('Pairing rationale','<textarea name="rationale" required rows="2" placeholder="Why this discharge station and date support this sample"></textarea>')}<button>Create paired-load report</button></form><div id="mw-load-result"></div></section><section class="mw-panel"><h2>Reopen previous results</h2><p>Saved result snapshots preserve their original source revision, selected settings and full populations.</p><button data-tab="results">Open saved results</button></section>`;}
  function renderArchive(){area.innerHTML=`<section class="mw-panel"><h2>Complete retained sources</h2><p>Original text is immutable. Reimports deduplicate; revised source results remain inspectable alternatives.</p>${!summary.imports.length?'<p class="mw-empty">No sources have been imported.</p>':''}${summary.imports.map(s=>`<details class="mw-station"><summary><strong>${esc(s.label)}</strong> <span>${num(s.summary.rows)} rows · ${num(s.summary.rejectedCount)} rejected</span></summary><dl><dt>Imported</dt><dd>${esc(stamp(s.createdAt))}</dd><dt>SHA-256</dt><dd class="mw-mono">${esc(s.sha)}</dd></dl><div class="mw-buttons"><a class="mw-button" href="${base}/sources/${s.id}/original" download>Original file</a><a class="mw-button" href="${base}/sources/${s.id}/rejected" download>Complete rejected rows</a><button data-source="${s.id}">Inspect retrieval provenance</button></div><div data-source-detail="${s.id}"></div></details>`).join('')}</section>`;}
  async function loadHistory(){history=await api('/exports?offset='+historyOffset+'&limit=20');if(dead)return;renderResults();}
  async function showResult(report,id){result=report;resultId=id||'';resultOffsets={};tab='results';summary=await api();if(dead)return;statBar();await loadHistory();}
  function renderResults(){
